        self.attributes = AttributesApi(client)
        self.audit = AuditApi(client)
        self.auth = AuthApi(client)
        self.authz = AuthzApi(client)
        self.dashboard = DashboardApi(client)
        self.health = HealthApi(client)
        self.permissions = PermissionsApi(client)
        self.policies = PoliciesApi(client)
        self.policy_bindings = PolicyBindingsApi(client)
        self.relation_definitions = RelationDefinitionsApi(client)
        self.relation_tuples = RelationTuplesApi(client)
        self.resource_types = ResourceTypesApi(client)
        self.resources = ResourcesApi(client)
        self.roles = RolesApi(client)
        self.setup = SetupApi(client)
        self.users = UsersApi(client)
